spells.css:
.compare-container {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-md);
  aspect-ratio: 16 / 9;
  timeline-scope: --compare;
}

.compare-img {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  pointer-events: none;
}

.compare-before-wrap {
  position: absolute;
  inset: 0;
  width: 100%;
  border-right: 2px solid white;
  box-shadow: 4px 0 16px oklch(0 0 0 / 0.3);
  pointer-events: none;
}

.compare-scroller {
  position: absolute;
  inset: 0;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
  z-index: 10;
  scroll-timeline: --compare inline;
}
.compare-scroller::-webkit-scrollbar { display: none; }

.scroller-spacer {
  width: 200%;
  height: 100%;
  pointer-events: none;
}

@supports (animation-timeline: scroll()) {
  .compare-before-wrap {
    animation: reveal-before linear both;
    animation-timeline: --compare;
  }

  @keyframes reveal-before {
    from { clip-path: inset(0 0% 0 0); }
    to   { clip-path: inset(0 100% 0 0); }
  }
}

