spells.css:
.avatar-cluster {
  display: flex;
  align-items: center;
  gap: .4rem;
  padding: 1rem;
  margin: 0;
  list-style: none;
}
.avatar-cluster > li {
  inline-size: 2.75rem;
  block-size: 2.75rem;
  display: grid;
  place-items: center;
  border: 2px solid var(--color-bg);
  border-radius: 50%;
  background: var(--color-primary);
  color: var(--color-text-inverse);
  font-weight: 750;
}
.avatar-cluster > li:nth-child(3n + 1) { rotate: -4deg; translate: 0 -2px; }
.avatar-cluster > li:nth-child(3n + 2) { rotate:  3deg; translate: 0  2px; }
.avatar-cluster > li:nth-child(3n)     { rotate: -1deg; translate: 0  1px; }
@supports (rotate: random(-1deg, 1deg)) {
  .avatar-cluster > li {
    rotate: random(-6deg, 6deg);
    translate: 0 random(-3px, 3px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .avatar-cluster > li {
    rotate: 0deg;
    translate: 0;
  }
}

